@_mutmut_mutated(mutants_x_canonical_json_bytes__mutmut)
def canonical_json_bytes(value: object) -> bytes:
    """Return UTF-8 canonical JSON bytes suitable for stable SHA-256 hashing."""
    return json.dumps(
        value,
        ensure_ascii=True,
        allow_nan=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")


